;\n}\n\n.nav-btn[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  background: #f8f9fa;\n  color: #495057;\n  border: 1px solid #dee2e6;\n  padding: 0.75rem 1.5rem;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s;\n  font-weight: 500;\n}\n\n.nav-btn[_ngcontent-%COMP%]:hover {\n  background: #e9ecef;\n  border-color: #adb5bd;\n}\n\n.nav-btn.prev[_ngcontent-%COMP%] {\n  margin-right: auto;\n}\n\n.nav-btn.next[_ngcontent-%COMP%] {\n  margin-left: auto;\n}\n\n@media (max-width: 768px) {\n  .container[_ngcontent-%COMP%] {\n    padding: 1rem;\n  }\n  .header[_ngcontent-%COMP%] {\n    flex-direction: column;\n    align-items: flex-start;\n    gap: 1rem;\n  }\n  .header-controls[_ngcontent-%COMP%] {\n    align-self: flex-end;\n  }\n  .surah-title[_ngcontent-%COMP%] {\n    font-size: 1.25rem;\n  }\n  .verse-text[_ngcontent-%COMP%] {\n    font-size: 1.1rem;\n  }\n  .navigation[_ngcontent-%COMP%] {\n    flex-direction: column;\n  }\n  .nav-btn.prev[_ngcontent-%COMP%], .nav-btn.next[_ngcontent-%COMP%] {\n    margin: 0;\n  }\n  .floating-font-controls[_ngcontent-%COMP%] {\n    right: 0.5rem;\n    padding: 0.5rem;\n  }\n  .font-control-btn[_ngcontent-%COMP%] {\n    width: 28px;\n    height: 28px;\n  }\n}\n/*# sourceMappingURL=data:application/json;charset=utf-8;base64, */"]
